{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes (e.g., after 70+ peaks, cap forecast at 10% below peak).",
    "Adjust downward for sentiment > 0.0 (positive sentiment) — model tends to overreact; apply 5-10% downward bias.",
    "Apply mean reversion correction: if forecast deviates > 15% from 10-day moving average, revert toward it.",
    "For long-term (30d) forecasts, reduce volatility — model overestimates upward momentum; apply smoothing filter.",
    "If sentiment is negative (≤ -0.25), increase downward bias by 5-10% to counteract overconfidence in model.",
    "Avoid overfitting to recent highs — if last 3 days are above 70, reduce forecast by 5-8% to prevent lagged overreaction."
  ]
}
